Let me write:
```js
function resolveBounce(ball, brick) {
  // penetration on x
  const fromLeft = ball.x + ball.r - brick.x;      // to clear left edge
  const fromRight = brick.x + brick.w - (ball.x - ball.r); // to clear right edge
  const penX = Math.min(fromLeft, fromRight);

  const fromTop = ball.y + ball.r - brick.y;
  const fromBottom = brick.y + brick.h - (ball.y - ball.r);
  const penY = Math.min(fromTop, fromBottom);

  if (penX < penY) {
    // side hit: flip vx
    if (fromLeft < fromRight) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  } else if (penY < penX) {
    // top/bottom hit: flip vy
    if (fromTop < fromBottom) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  } else {
    // corner: flip both
    // push out diagonally
    if (fromLeft < fromRight) { ball.x = brick.x - ball.r; ball.vx = -Math.abs(ball.vx); }
    else { ball.x = brick.x + brick.w + ball.r; ball.vx = Math.abs(ball.vx); }
    if (fromTop < fromBottom) { ball.y = brick.y - ball.r; ball.vy = -Math.abs(ball.vy); }
    else { ball.y = brick.y + brick.h + ball.r; ball.vy = Math.abs(ball.vy); }
  }
}
```

