```js
function penetration(ball, brick) {
  const fromLeft = ball.x + ball.r - brick.x;
  const fromRight = brick.x + brick.w - (ball.x - ball.r);
  const penX = Math.min(fromLeft, fromRight);
  const fromTop = ball.y + ball.r - brick.y;
  const fromBottom = brick.y + brick.h - (ball.y - ball.r);
  const penY = Math.min(fromTop, fromBottom);
  return { penX, penY, fromLeft, fromRight, fromTop, fromBottom };
}

export function resolveBounce(ball, brick) {
  const p = penetration(ball, brick);
  if (p.penX < p.penY) {
    // side hit
    if (p.fromLeft < p.fromRight) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  } else if (p.penY < p.penX) {
    // top/bottom hit
    if (p.fromTop < p.fromBottom) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  } else {
    // corner: flip both
    if (p.fromLeft < p.fromRight) { ball.x = brick.x - ball.r; ball.vx = -Math.abs(ball.vx); }
    else { ball.x = brick.x + brick.w + ball.r; ball.vx = Math.abs(ball.vx); }
    if (p.fromTop < p.fromBottom) { ball.y = brick.y - ball.r; ball.vy = -Math.abs(ball.vy); }
    else { ball.y = brick.y + brick.h + ball.r; ball.vy = Math.abs(ball.vy); }
  }
  return true;
}

export function brickBounce(ball, bricks) {
  // find colliding live bricks
  const hits = bricks.filter((b) => b.alive && collides(ball, b));
  if (hits.length === 0) return false;
  // choose the shallowest hit as the bounce face
  let face = hits[0];
  let best = infinity;
  for (const b of hits) {
    const p = penetration(ball, b);
    const d = Math.min(p.penX, p.penY);
    if (d < best) { best = d; face = b; }
  }
  resolveBounce(ball, face);
  return true;
}
