// --- Issue #1: brick bounce -------------------------------------------------
// The ball used to plow straight through bricks: frame() destroyed the hit
// brick but never deflected the ball. These tests lock in the per-face bounce,
// the corner case, push-out, the single-bounce seam rule and tunnelling.

test('bounce: top face hit flips vy only (vx untouched)', () => {
  const ball = { x: 110, y: 105, r: 7, vx: 30, vy: 100 };
  const brick = { x: 90, y: 110, w: 40, h: 20 };
  resolveBounce(ball, brick);
  assert.equal(Math.sign(ball.vy), UP, 'vy should flip to climb back up');
  assert.equal(ball.vx, 30, 'vx must be left exactly as it was');
  assert.equal(ball.y, brick.y - ball.r, 'ball pushed above the brick');
});

test('bounce: side face hit flips vx only (vy untouched)', () => {
  const ball = { x: 85, y: 100, r: 7, vx: 50, vy: -20 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  resolveBounce(ball, brick);
  assert.equal(Math.sign(ball.vx), LEFT, 'vx should flip to the left');
  assert.equal(ball.vy, -20, 'vy must be left exactly as it was');
  assert.equal(ball.x, brick.x - ball.r, 'ball pushed left of the brick');
});

test('bounce: bottom face hit flips vy upward to downward', () => {
  const ball = { x: 110, y: 115, r: 7, vx: 30, vy: -100 };
  const brick = { x: 90, y: 90, w: 40, h: 20 }; // bottom edge at 110
  resolveBounce(ball, brick);
  assert.equal(Math.sign(ball.vy), DOWN, 'vy should flip to go back down');
  assert.equal(ball.vx, 30, 'vx must be left exactly as it was');
  assert.equal(ball.y, brick.y + brick.h + ball.r, 'ball pushed below the brick');
});

test('bounce: corner hit (equal penetration) flips both axes', () => {
  const ball = { x: 95, y: 95, r: 7, vx: 50, vy: -30 };
  const brick = { x: 100, y: 100, w: 40, h: 20 };
  resolveBounce(ball, brick);
  assert.equal(Math.sign(ball.vx), LEFT);
  assert.equal(Math.sign(ball.vy), UP);
});

test('bounce: ball is pushed out so it no longer overlaps the brick', () => {
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  const ball = { x: 110, y: 105, r: 7, vx: 30, vy: 100 };
  resolveBounce(ball, brick);
  assert.equal(collides(ball, brick), false, 'must not still overlap (sticky)');
});

test('bounce: seam hitting two bricks flips vy exactly ONCE', () => {
  const brick1 = { x: 90, y: 90, w: 40, h: 20, alive: true };
  const brick2 = { x: 130, y: 90, w: 40, h: 20, alive: true };
  const ball = {
    x: 130, y: 88, r: 7, vx: 0, vy: 100,
    _px: 130, _py: 76, // falling from above, straddling the seam
  };
  const hits = brickBounce(ball, [brick1, brick2]);
  assert.equal(hits.length, 2, 'both seam neighbours are hit in one pass');
  assert.equal(Math.sign(ball.vy), UP, 'vy flipped exactly once (not cancelled)');
  assert.equal(ball.vx, 0, 'vx untouched by a pure top hit');
});

test('bounce: tunnelling through a brick is detected and deflected', () => {
  const brick = { x: 90, y: 100, w: 40, h: 20, alive: true };
  // Ball teleports from below the brick to above it in a single step.
  const ball = {
    x: 100, y: 70, r: 7, vx: 0, vy: -500,
    _px: 100, _py: 132, // previous position below the brick
  };
  const hits = brickBounce(ball, [brick]);
  assert.equal(hits.length, 1, 'tunnelled brick still counts as a hit');
  assert.equal(Math.sign(ball.vy), DOWN, 'should be deflected back downward');
  assert.ok(ball.y > brick.y + brick.h, 'ball parked below the brick');
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

