export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Issue #1: brick bounce ------------------------------------------------
//
// The bounce is a per-face resolution, not a blanket velocity flip:
//   * the axis with the SMALLER penetration is the face that was hit;
//   * flip `vy` on a top/bottom hit, `vx` on a side hit, and leave the other
//     component exactly as it was;
//   * equal penetrations mean a diagonal/corner hit — flip both;
//   * push the ball back OUT of the brick, otherwise it still overlaps next
//     frame and re-flips forever (sticky bounce).

// How far the ball pokes into the brick along each axis, plus the side of each
// entry (so we know which direction to push the ball back out).
function penetration(ball, brick) {
  const fromLeft = ball.x + ball.r - brick.x; // push the ball left to clear
  const fromRight = brick.x + brick.w - (ball.x - ball.r); // push right
  const fromTop = ball.y + ball.r - brick.y; // push up to clear
  const fromBottom = brick.y + brick.h - (ball.y - ball.r); // push down
  return {
    penX: Math.min(fromLeft, fromRight),
    penY: Math.min(fromTop, fromBottom),
    fromLeft,
    fromRight,
    fromTop,
    fromBottom,
  };
}

// Deflect a ball that overlaps a single brick, pushing it out along the face.
// Returns `true` (the ball has bounced) for convenience. Mutates `ball`.
export function resolveBounce(ball, brick) {
  const p = penetration(ball, brick);

  if (p.penX < p.penY) {
    // Side hit: flip vx, leave vy untouched.
    if (p.fromLeft < p.fromRight) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  } else if (p.penY < p.penX) {
    // Top/bottom hit: flip vy, leave vx untouched.
    if (p.fromTop < p.fromBottom) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  } else {
    // Corner: equal penetrations mean a diagonal hit — flip both.
    if (p.fromLeft < p.fromRight) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
    if (p.fromTop < p.fromBottom) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  }

  return true;
}

// Does the ball's sweep (previous -> current position) cross the brick, even
// though the ball is not inside it NOW? Samples the path; catches the discrete
// tunnelling jump at high speed (issue #1).
function sweptHit(px, py, ball, brick) {
  const dx = ball.x - px;
  const dy = ball.y - py;
  const dist = Math.hypot(dx, dy);
  const n = Math.max(1, Math.ceil(dist / ball.r));
  for (let i = 1; i <= n; i++) {
    const t = i / n;
    if (
      px + dx * t + ball.r > brick.x &&
      px + dx * t - ball.r < brick.x + brick.w &&
      py + dy * t + ball.r > brick.y &&
      py + dy * t - ball.r < brick.y + brick.h
    ) {
      return true;
    }
  }
  return false;
}

// When the ball has tunnelled clean through a brick, bounce it back off the
// face it entered from (deduced from the previous position which is still on
// the entry side of the brick).
function resolveTunnel(ball, brick) {
  const p = ball._px != null ? ball._px : ball.x;
  const q = ball._py != null ? ball._py : ball.y;
  const approachedFromLeft = p + ball.r <= brick.x;
  const approachedFromRight = p - ball.r >= brick.x + brick.w;
  const approachedFromTop = q + ball.r <= brick.y;
  const approachedFromBottom = q - ball.r >= brick.y + brick.h;

  if (approachedFromBottom) {
    ball.y = brick.y + brick.h + ball.r;
    ball.vy = Math.abs(ball.vy);
  } else if (approachedFromTop) {
    ball.y = brick.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
  } else if (approachedFromRight) {
    ball.x = brick.x + brick.w + ball.r;
    ball.vx = Math.abs(ball.vx);
  } else {
    ball.x = brick.x - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }
}

// The integrated brick pass: sweep + contact detection, resolve the bounce
// EXACTLY ONCE even when a seam overlaps two bricks in the same pass (a naive
// per-brick loop would flip vy for brick 1 then undo it on brick 2 and the
// ball would sail through). Returns the array of bricks that were hit so the
// caller can destroy them and award score.
export function brickBounce(ball, bricks) {
  const px = ball._px != null ? ball._px : ball.x;
  const py = ball._py != null ? ball._py : ball.y;

  const contacts = [];
  const tunnels = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (collides(ball, brick)) {
      contacts.push(brick);
    } else if (sweptHit(px, py, ball, brick)) {
      tunnels.push(brick);
    }
  }

  if (contacts.length === 0 && tunnels.length === 0) {
    return [];
  }

  if (contacts.length > 0) {
    // The shallowest contact is the face actually struck; resolve against it
    // once and push out — that clears a shared row seam and prevents double
    // flips on the neighbouring brick.
    let face = contacts[0];
    let best = Infinity;
    for (const b of contacts) {
      const p = penetration(ball, b);
      const d = Math.min(p.penX, p.penY);
      if (d < best) {
        best = d;
        face = b;
      }
    }
    resolveBounce(ball, face);
  } else {
    resolveTunnel(ball, tunnels[0]);
  }

  // The ball is now moving away; collect the union of touched bricks so the
  // caller breaks every one of them (and awards score) but never bounces twice.
  return contacts.concat(tunnels);
}

